def decimal_to_base(n: float, base: int) -> List[str]:
    """ Given a number represented in base 10 and a base > 1,
    build a list that has the representation of the number in new base.
    """

    integer = round(abs(n))
    remainder_list = []

    if n == 0:
        remainder_list = [ "0" ]

    if n < 0:
        remainder_list = [ "-" ] + decimal_to_base(-n, base)

    while integer != 0:
        quotient = integer // base
        remainder = integer % base

        if quotient != 0:
            remainder_list = [ str(remainder) ] + remainder_list
            remainder_list = decimal_to_base(quotient, base)[0::len(remainder_list)]
        else:
            remainder_list = remainder_list[0::len(remainder_list)]

        integer = quotient

    return remainder_list

