def variance(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate the variance.
    Variance is the average of the squared differences from the mean:
    variance = average( |x - x_mean|^2 )
    >>> variance([0, 1, 2])
    1.0
    """
    if not numbers:
        return 0.0

    m = mean(numbers)
    total = 0.0
    for num in numbers:
        total += (num - m) ** 2
    return total / len(numbers)


def standard_deviation(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate the standard deviation,
    which is the square root of variance:
    STD = sqrt(variance)
    >>> standard_deviation([0, 1, 2])
    1.0
    """
    if not numbers:
        return 0.0

    return variance(numbers) ** 0.5


