@lru_cache(maxsize=None)
def fib(n: int) -> int:
    """ Given an index n, return the value stored in the table of
    Fibonnaci series

    >>> fib(3)
    2
    >>> fib(6)
    8
    """
    if n <= 1:
        return n

    return fib(n - 1) + fib(n - 2)


