from functools import lru_cache


@lru_cache(maxsize=None)
def ncr(n: int, r: int) -> int:
    """ Calculate the number of ways to choose r elements from a set of n elements.
    """
    if r == 0 or r == n:
        return 1
    if r == 1:
        return n
    return ncr(n - 1, r - 1) + ncr(n - 1, r)


@lru_cache(maxsize=None)
def combinatorial_number(n: int, k: int) -> int:
    """ Calculate the number of ways to choose k elements from a set of n elements,
    which is part of the binomial coefficient.
    """
    if k == 0 or k == n:
        return 1
    return combinatorial_number(n - 1, k - 1)


